{
  "findings": [
    {
      "check_id": "CKV_AZURE_224",
      "title": "Ensure that the Ledger feature is enabled on database that requires cryptographic proof and nonrepudiation of data integrity",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The Ledger feature is not enabled on the Azure SQL database. This feature ensures cryptographic proof and nonrepudiation of data integrity, which is critical for sensitive or regulated data."
    },
    {
      "check_id": "CKV_AZURE_229",
      "title": "Ensure the Azure SQL Database Namespace is zone redundant",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The Azure SQL database is not configured to be zone redundant. Zone redundancy ensures high availability and resilience against zone-level failures."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"main\" {\n  name           = \"${var.project_name}-database\"\n  server_id      = azurerm_mssql_server.main.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 20\n  sku_name       = \"S0\"\n  tags           = var.common_tags\n\n  ledger_enabled = true\n  zone_redundant = true\n}",
  "fix_summary": "Enabled the Ledger feature for cryptographic proof and nonrepudiation of data integrity. Configured the database to be zone redundant for high availability and resilience."
}
